+export interface NotificationPort {
+  /** Post or update a feature-level Slack message. */
+  postFeatureMessage(
+    featureId: string,
+    trigger: FeatureTrigger,
+    context: FeatureContext,
+  ): Promise<void>;
+
+  /** Post the final feature message and clean up the feature thread mapping. */
+  closeFeatureThread(featureId: string, context: FeatureContext): Promise<void>;
+
+  /** Post or update a task-level Slack message. */
