+    featureId: string,
+    taskId: string,
+    trigger: TaskTrigger,
+    context: TaskContext,
+  ): Promise<void>;
+
+  /** Post the final task message and clean up the task thread mapping. */
+  closeTaskThread(
+    featureId: string,
+    taskId: string,
+    context: TaskContext,
+  ): Promise<void>;
+}
